// Writes the contract ABI into the web app as a typed TS constant.
//   npm run export-abi
const fs = require("fs");
const path = require("path");
const { artifacts } = require("hardhat");

async function main() {
  const { abi } = await artifacts.readArtifact("DrugReportRegistry");
  const out = path.join(__dirname, "..", "..", "web", "lib", "abi.ts");
  fs.writeFileSync(
    out,
    "// Generated by contracts/scripts/export-abi.js. Do not edit by hand.\n" +
      `export const registryAbi = ${JSON.stringify(abi, null, 2)} as const;\n`
  );
  console.log(`Wrote ${path.relative(process.cwd(), out)}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
